#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *p = (long long *)malloc(N * sizeof(long long));
    long long sum = 0, pos = 0;
    p[0] = 0;

    for (int i = 0; i < N; i++) {
        long long x;
        scanf("%lld", &x);
        sum += x;
        if (i < N - 1) {
            pos += x;
            p[i + 1] = pos;
        }
    }

    if (sum % 2 != 0) {
        printf("N\n");
        free(p);
        return 0;
    }

    long long target = sum / 2;
    int count = 0;

    for (int i = 0; i < N && p[i] < target; i++) {
        long long q = p[i] + target;
        int lo = 0, hi = N - 1, found = 0;

        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (p[mid] == q) {
                found = 1;
                break;
            } else if (p[mid] < q) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        if (found) {
            count++;
            if (count >= 2) break;
        }
    }

    if (count >= 2)
        printf("S\n");
    else
        printf("N\n");

    free(p);
    return 0;
}
